def valid(money, cost, name):
    if not (type(money) is int and 1000 <= money <= 500000):
        return False
    if not (isinstance(cost, list) and isinstance(name, list) and 3 <= len(cost) <= 100 and len(name) == len(cost)):
        return False
    for c in cost:
        if not (isinstance(c, list) and len(c) == 2 and all(type(x) is int for x in c)):
            return False
        if not (10 <= c[0] <= 100 and 1000 <= c[1] <= 10000):
            return False
    if len(set(c[1] for c in cost)) > 2:
        return False
    if not any(money >= c[1] for c in cost):
        return False
    return all(isinstance(n, str) and 1 <= len(n) <= 10 for n in name) and len(set(name)) == len(name)

